-- Backfill activities_field_trips_divisions from activities that have division_id
SELECT id, division_id, company_id FROM public.activities_field_trips WHERE division_id IS NOT NULL ON CONFLICT (activity_id, division_id) DO NOTHING;

-- Backfill sports_calendar_divisions from sports_calendar that have division_id
SELECT id, division_id, company_id FROM public.sports_calendar WHERE division_id IS NOT NULL ON CONFLICT (sports_event_id, division_id) DO NOTHING;